import{E as e,T as t}from"./index-V8vxoNhV.js";var n={"infer-intro":[`Suy luận thống kê là dùng một mẫu nhỏ để kết luận về cả tập lớn, và luôn kèm mức bất định.`,`Inferential statistics uses a small sample to conclude about the whole population, always with a stated uncertainty.`],permut:[`Hoán vị (thứ tự quan trọng): P(n,k) = n! / (n−k)!.`,`Permutation (order matters): P(n,k) = n! / (n−k)!.`],combin:[`Tổ hợp (thứ tự không quan trọng): C(n,k) = n! / (k!(n−k)!), tức hoán vị chia cho k!.`,`Combination (order doesn't matter): C(n,k) = n! / (k!(n−k)!), i.e. the permutation divided by k!.`],"prob-def":[`Xác suất là số từ 0 đến 1: 0 là không thể, 1 là chắc chắn, và P(không A) = 1 − P(A).`,`Probability is a number from 0 to 1: 0 is impossible, 1 is certain, and P(not A) = 1 − P(A).`],events:[`Loại trừ nhau là không thể cùng xảy ra; độc lập là biết cái này không đổi xác suất cái kia, và hai biến cố loại trừ nhau (xác suất > 0) thì không độc lập.`,`Mutually exclusive means they cannot happen together; independent means knowing one doesn't change the other, and exclusive events with positive probability are not independent.`],"add-rule":[`P(A hoặc B) = P(A) + P(B) − P(A và B); phải trừ phần chung vì nó bị đếm hai lần.`,`P(A or B) = P(A) + P(B) − P(A and B); subtract the overlap because it is counted twice.`],"mul-rule":[`P(A và B) = P(A) × P(B | A); chỉ khi hai biến cố độc lập mới nhân thẳng P(A) × P(B).`,`P(A and B) = P(A) × P(B | A); only when A and B are independent does it reduce to P(A) × P(B).`],rv:[`Biến ngẫu nhiên là quy tắc gán một con số cho mỗi kết quả của một phép thử ngẫu nhiên.`,`A random variable is a rule that assigns a number to each outcome of a random experiment.`],dist:[`Phân phối xác suất cho biết mỗi giá trị có bao nhiêu xác suất, và tổng tất cả bằng 1.`,`A probability distribution says how much probability each value has, and they all add up to 1.`],ev:[`Giá trị kỳ vọng E[X] = Σ x · P(X = x): mức trung bình sau rất nhiều lần lặp lại.`,`Expected value E[X] = Σ x · P(X = x): the long-run average over many repeats.`],"no-exp":[`Có thể tính xác suất từ một mô hình giả định mà chưa cần quan sát dữ liệu thật.`,`You can compute a probability from an assumed model before observing any real data.`],binomial:[`Nhị thức đếm số lần thành công trong n lần thử độc lập, cùng xác suất p: P(X=k) = C(n,k) pᵏ (1−p)ⁿ⁻ᵏ.`,`Binomial counts successes in n independent tries with the same p: P(X=k) = C(n,k) pᵏ (1−p)ⁿ⁻ᵏ.`],cdf:[`Xác suất tích lũy F(k) = P(X ≤ k): cộng dồn từ giá trị nhỏ nhất đến mốc k.`,`Cumulative probability F(k) = P(X ≤ k): add up from the smallest value to the cutoff k.`],pdf:[`Với biến liên tục, xác suất của một khoảng là diện tích dưới đường mật độ; xác suất tại đúng một điểm bằng 0.`,`For a continuous variable, the probability of a range is the area under the density curve; the probability at one exact point is 0.`],normal:[`Phân phối chuẩn là hình chuông đối xứng, chỉ cần trung bình μ và độ lệch chuẩn σ là xác định hoàn toàn.`,`The normal distribution is a symmetric bell fully set by the mean μ and the standard deviation σ.`],zscore:[`z = (x − μ) / σ: cho biết x cách trung bình bao nhiêu độ lệch chuẩn, âm là thấp hơn, dương là cao hơn.`,`z = (x − μ) / σ: how many standard deviations x is from the mean, negative below and positive above.`],samples:[`Mẫu là một phần lấy ra từ tổng thể để nói về phần bạn chưa đo; mẫu nhỏ chưa phải cả tổng thể.`,`A sample is a part drawn from the population to speak about the part you didn't measure; it is not the whole.`],"samp-dist":[`Phân phối mẫu là phân phối của một thống kê (như trung bình mẫu) khi lấy mẫu lặp lại; độ lệch chuẩn của nó là sai số chuẩn SE = σ / √n.`,`A sampling distribution is the distribution of a statistic (such as the sample mean) over repeated sampling; its standard deviation is the standard error SE = σ / √n.`],"samp-props":[`Lấy mẫu công bằng thì trung bình các trung bình mẫu bằng μ, và n càng lớn thì Var = σ²/n càng nhỏ; mẫu lớn không sửa được mẫu chệch.`,`With fair sampling the mean of sample means equals μ, and a larger n shrinks Var = σ²/n; a bigger sample doesn't fix a biased draw.`],clt:[`Định lý giới hạn trung tâm: với n đủ lớn (thường quanh 30, lệch nhiều thì cần lớn hơn), trung bình mẫu xấp xỉ chuẩn N(μ, σ²/n) dù dữ liệu gốc không chuẩn.`,`Central Limit Theorem: for large enough n (often around 30, more if skewed), the sample mean is approximately N(μ, σ²/n) even if the data are not normal.`],"clt-est":[`Ước lượng trung bình: đừng nói một con số, hãy nói một khoảng x̄ ± z·s/√n quanh trung bình mẫu.`,`Estimating a mean: don't give one number, give a range x̄ ± z·s/√n around the sample mean.`],ci:[`Khoảng tin cậy 95% nói về phương pháp: lặp lại nhiều lần thì khoảng chứa giá trị thật khoảng 95% số lần, chứ không phải xác suất 95% cho riêng một khoảng.`,`A 95% confidence interval describes the method: repeated many times, about 95% of the intervals contain the true value; it is not a 95% chance for one particular interval.`],"samp-types":[`Cách lấy mẫu là một phần của kết luận: mẫu chệch thì kết luận chệch, và khoảng tin cậy không sửa được điều đó.`,`How you sample is part of the conclusion: a biased draw gives a biased conclusion, and a confidence interval can't repair it.`],"samp-use":[`Dùng mẫu khi đo cả tổng thể quá tốn kém hoặc không cần thiết, và mẫu phải giống tổng thể.`,`Use a sample when measuring the whole population is too costly or unnecessary, and it must resemble the population.`],joint:[`Xác suất đồng thời là cả hai cùng xảy ra; xác suất có điều kiện P(A | B) = P(A và B) / P(B), và P(A | B) khác P(B | A).`,`Joint probability is both happening; conditional probability P(A | B) = P(A and B) / P(B), and P(A | B) is not P(B | A).`],bayes:[`Bayes: P(A | B) = P(B | A) · P(A) / P(B); xác suất ban đầu được cập nhật khi có thông tin mới.`,`Bayes: P(A | B) = P(B | A) · P(A) / P(B); the starting probability is updated when new information arrives.`],"samp-est":[`Ước lượng điểm (như p̂ = số thuận lợi / n) chỉ là một con số từ mẫu, không phải giá trị thật; cần kèm một khoảng.`,`A point estimate (like p̂ = favorable / n) is one number from the sample, not the true value; pair it with a range.`],"ht-rule":[`Đặt mức ý nghĩa α và đường bác bỏ trước khi nhìn dữ liệu; chọn sau khi thấy số là gian lận.`,`Set the significance level α and the rejection line before looking at the data; choosing them after seeing the numbers is cheating.`],"ht-h0":[`H0 là câu mặc định («không có khác biệt») dùng để tính độ hiếm của mẫu; H1 là hướng bạn nghi ngờ.`,`H0 is the default statement ("no difference") used to compute how rare the sample is; H1 is the direction you suspect.`],"ht-p":[`p-value là xác suất ra kết quả ít nhất lệch như mẫu này nếu H0 đúng; nó không phải xác suất H0 đúng.`,`The p-value is the probability of a result at least this far off if H0 is true; it is not the probability that H0 is true.`],"ht-err":[`Sai lầm loại I là báo động giả (bác bỏ H0 đúng, xác suất α); loại II là bỏ sót (giữ H0 sai).`,`A type I error is a false alarm (rejecting a true H0, probability α); a type II error is a miss (keeping a false H0).`],"ht-t":[`Khi σ phải ước lượng từ mẫu thì dùng phân phối t: đuôi dày hơn chuẩn, nên đường bác bỏ lùi ra xa hơn.`,`When σ must be estimated from the sample, use the t distribution: heavier tails than the normal, so the rejection line sits farther out.`],"ht-means":[`Kiểm định hai trung bình hỏi: nếu thực tế không có chênh lệch thì khoảng cách giữa hai trung bình này có hiếm không; t = (x̄₁ − x̄₂) / SE.`,`The two-sample mean test asks: if there is truly no gap, is this gap rare; t = (x̄₁ − x̄₂) / SE.`],"ht-props":[`Kiểm định hai tỷ lệ hỏi chênh lệch giữa hai tỷ lệ có hiếm không; chênh lệch nhìn thấy được vẫn có thể là nhiễu: z = (p̂₁ − p̂₂) / SE.`,`The two-proportion test asks whether the difference between two rates is rare; a visible gap can still be noise: z = (p̂₁ − p̂₂) / SE.`],"ht-peek":[`Mỗi lần nhìn và cho phép dừng là thêm một cơ hội báo động giả, nên dừng thử nghiệm A/B ngay khi đẹp thì 5% không còn là 5%.`,`Every look at which you allow yourself to stop is another chance of a false alarm, so stopping an A/B test the moment it looks good makes 5% no longer 5%.`],"ht-chi":[`Kiểm định chi bình phương nhìn cả bảng cùng lúc: χ² = Σ (O − E)² / E, với O là số đếm thật và E là số đếm kỳ vọng nếu độc lập.`,`The chi-squared test looks at the whole table at once: χ² = Σ (O − E)² / E, where O is the observed count and E the count expected under independence.`],"ht-anova":[`ANOVA so ba nhóm trở lên bằng một kiểm định: F = MS giữa nhóm / MS trong nhóm; F lớn nghĩa là các nhóm khác nhau nhiều hơn mức nhiễu.`,`ANOVA compares three or more groups with one test: F = MS between / MS within; a large F means the groups differ more than noise would.`],"eda-ask":[`Đặt câu hỏi trước khi vẽ biểu đồ: EDA là kiểm tra một câu hỏi, không phải đi tìm hình đẹp để kể.`,`Ask the question before drawing the chart: EDA checks a question; it is not a hunt for a picture worth telling.`],"eda-src":[`Nguồn dữ liệu quyết định điều bạn được phép nói; không phải bảng số nào cũng là khách hàng của bạn.`,`The source of the data decides what you may say; not every table of numbers is your customers.`],"eda-type":[`Mỗi cột có kiểu riêng (số, chữ, ngày) và chỉ nhận các phép tính hợp kiểu; lấy trung bình của tên hay cộng hai ngày là đọc sai kiểu.`,`Each column has its own type (number, text, date) and only the operations that fit it; averaging a name or adding two dates misreads the type.`],"eda-row":[`Mỗi dòng nên là một thực thể; hai dòng cùng khóa thì mọi tổng phía sau bị thổi phồng.`,`Each row should be one entity; if two rows share a key, every total downstream is inflated.`],"eda-miss":[`Ô trống nghĩa là chưa biết, không phải bằng 0; đổi trống thành 0 là bịa dữ liệu.`,`A blank means unknown, not zero; turning a blank into 0 is inventing data.`],"eda-out":[`Điểm ngoại lai là cờ cảnh báo, không phải bản án: kiểm tra rồi mới quyết định giữ hay bỏ.`,`An outlier is a warning flag, not a verdict: check it before deciding to keep or drop it.`],"eda-scale":[`Chuẩn hóa z = (x − x̄) / s đưa các cột về cùng một thước đo; nó không tạo ra quan hệ mới giữa các cột.`,`Standardising z = (x − x̄) / s puts columns on one ruler; it does not create a new relationship between them.`],"eda-bad":[`Giá trị không hợp lệ là giá trị không thể xảy ra theo định nghĩa của cột (như 200%); khác với giá trị hiếm nhưng có thật.`,`An invalid value is one that cannot happen by the column's definition (like 200%); it differs from a rare but real value.`],"eda-cat":[`Cột phân loại không thứ tự mô tả bằng số đếm và phần trăm, không nối bằng đường.`,`An unordered categorical column is described with counts and percentages, not joined by a line.`],"eda-ord":[`Cột có thứ tự phải vẽ theo thứ tự, và chỉ một số trung bình có thể che mất hai đầu cực.`,`An ordered column must be drawn in order, and a mean alone can hide the two extremes.`],"eda-num":[`Trung bình bị kéo về phía đuôi, trung vị đứng giữa dãy đã sắp xếp; hai số lệch nhau thì phải nói cả cái đuôi.`,`The mean is pulled toward the tail while the median sits in the middle of the sorted list; when they differ, tell the tail too.`],"eda-r":[`r = cov(x, y) / (sₓ·s_y) đo hai cột cùng biến thiên theo đường thẳng, từ −1 đến 1; nó không phải tỷ lệ điểm nằm trên đường.`,`r = cov(x, y) / (sₓ·s_y) measures how two columns move together along a straight line, from −1 to 1; it is not the share of points on the line.`],"eda-cause":[`Tương quan là hai cột cùng đi; nhân quả là đổi một cột thì cột kia đổi khi mọi thứ khác giữ nguyên; biểu đồ phân tán không chứng minh được điều thứ hai.`,`Correlation is two columns moving together; causation is one changing the other with everything else held fixed; a scatter plot cannot prove the second.`],"eda-group":[`Cột số gặp cột chữ thì so sánh theo nhóm; không có hệ số tương quan cho một cái tên.`,`When a numeric column meets a text column, compare by group; there is no correlation coefficient for a name.`],"eda-tab":[`Hai cột chữ tạo thành bảng đếm, và một phần trăm phải nói rõ nó là phần của cái gì (mẫu số).`,`Two text columns form a table of counts, and a percentage must say what it is a share of (the denominator).`],"eda-flip":[`Tỷ lệ gộp có thể ngược với tỷ lệ trong từng nhóm (nghịch lý Simpson); nhóm bị trộn là một phần của câu trả lời.`,`A pooled rate can run opposite to the rate inside each group (Simpson's paradox); the mixed group is part of the answer.`],"sql-wh":[`Hệ thống đang chạy ghi cái vừa xảy ra, kho dữ liệu giữ lịch sử để trả lời câu hỏi dài hạn; đừng bắt một bảng làm cả hai việc.`,`The live system records what just happened; the warehouse keeps history for long-range questions; don't make one table do both jobs.`],"sql-star":[`Lược đồ sao: bảng sự kiện (fact) ở giữa, bảng danh mục (dimension) xung quanh, và độ mịn của bảng giữa phải nói được trong một câu.`,`Star schema: the fact table in the middle, dimension tables around it, and the grain of the middle table must be sayable in one sentence.`],"sql-key":[`Khóa chính là danh tính của một dòng; khóa ngoại là lời hứa rằng dòng nó trỏ tới có thật.`,`A primary key is the identity of a row; a foreign key is a promise that the row it points to is real.`],"sql-ddl":[`DDL (CREATE, ALTER, DROP) đổi cấu trúc bảng; DML (INSERT, UPDATE, DELETE) đổi dữ liệu trong bảng; nhầm hai nhóm này là cách mất bảng.`,`DDL (CREATE, ALTER, DROP) changes a table's structure; DML (INSERT, UPDATE, DELETE) changes the data in it; mixing them up is a way to lose a table.`],"sql-run":[`Thứ tự viết khác thứ tự chạy: FROM, WHERE, GROUP BY, HAVING rồi mới đến SELECT và ORDER BY.`,`Written order differs from running order: FROM, WHERE, GROUP BY, HAVING, and only then SELECT and ORDER BY.`],"sql-having":[`WHERE lọc dòng trước khi nhóm; HAVING lọc nhóm sau khi đã có tổng.`,`WHERE filters rows before grouping; HAVING filters groups after the totals exist.`],"sql-count":[`COUNT(*) đếm dòng, COUNT(cột) bỏ qua ô trống; ô trống không phải 0.`,`COUNT(*) counts rows, COUNT(column) skips blanks; a blank is not 0.`],"sql-join":[`JOIN ghép hai bảng theo khóa; khóa lặp thì dòng nhân lên, và INNER JOIN làm mất dòng không khớp.`,`JOIN pairs two tables by a key; a repeated key multiplies rows, and INNER JOIN drops rows with no match.`],"sql-left":[`LEFT JOIN giữ mọi dòng bên trái; chỗ không khớp bên phải là trống (NULL), không phải 0.`,`LEFT JOIN keeps every row on the left; a non-match on the right is blank (NULL), not 0.`],"sql-union":[`UNION xếp hai bảng chồng dọc (cùng cột); JOIN đặt hai bảng cạnh nhau theo khóa.`,`UNION stacks two tables vertically (same columns); JOIN places two tables side by side by key.`],"sql-win":[`Hàm cửa sổ tính một giá trị từ các dòng lân cận rồi dán lại vào từng dòng; bảng không bị thu nhỏ.`,`A window function computes a value from neighbouring rows and pastes it back on each row; the table doesn't shrink.`],"sql-rank":[`RANK chừa chỗ trống sau hòa (1, 1, 3), DENSE_RANK không (1, 1, 2), ROW_NUMBER phá hòa (1, 2, 3); chọn hàm là chọn luật hòa.`,`RANK leaves a gap after ties (1, 1, 3), DENSE_RANK doesn't (1, 1, 2), ROW_NUMBER breaks ties (1, 2, 3); choosing the function is choosing the tie rule.`],"sql-part":[`PARTITION BY tạo bảng xếp hạng riêng cho mỗi nhóm, bắt đầu lại từ 1, và không gộp dòng.`,`PARTITION BY creates a separate ranking for each group, restarting from 1, without collapsing rows.`],"sql-frame":[`Khung (frame) là tập dòng mà hàm được nhìn quanh dòng hiện tại, không phải cả partition; ba dòng chưa chắc là ba tuần.`,`A frame is the set of rows a function may look at around the current row, not the whole partition; three rows are not necessarily three weeks.`],"sql-lag":[`LAG và LEAD lấy giá trị dòng liền kề theo thứ tự sắp xếp; thiếu ngày trong dữ liệu thì «dòng trước» không phải hôm qua.`,`LAG and LEAD take the value of the adjacent row in sort order; if a day is missing from the data, the "previous row" is not yesterday.`],"sql-case":[`CASE là luật if viết ngay trong câu truy vấn để người khác chạy lại được.`,`CASE is an if-rule written right inside the query so someone else can rerun it.`],"sql-cte":[`CTE đặt tên cho một truy vấn con để dễ đọc; view lưu lại câu hỏi đó; không cái nào tự thành một bản sao dữ liệu.`,`A CTE names a subquery for readability; a view saves that question; neither automatically becomes a copy of the data.`],"sql-idx":[`Chỉ mục như mục lục của bảng: làm một loại truy vấn nhanh hơn, không làm nó đúng hơn hay đổi ý nghĩa câu lệnh.`,`An index is the table's table of contents: it makes one kind of query faster, not more correct, and doesn't change the statement's meaning.`],"ml-what":[`Học có giám sát học từ những dòng đã có đáp án rồi dự đoán đáp án cho dòng chưa có.`,`Supervised learning learns from rows that already have the answer, then predicts the answer for a row that doesn't.`],"slr-line":[`Hồi quy tuyến tính đơn: ŷ = β₀ + β₁x, một đường thẳng từ một cột đầu vào ra đáp án.`,`Simple linear regression: ŷ = β₀ + β₁x, one straight line from one input column to the answer.`],"slr-fit":[`Bình phương tối thiểu chọn hệ số chặn và độ dốc làm tổng bình phương phần dư RSS = Σ(y − ŷ)² nhỏ nhất.`,`Least squares picks the intercept and slope that make the residual sum of squares RSS = Σ(y − ŷ)² smallest.`],"slr-r2":[`R² = 1 − RSS/TSS là phần phương sai của y mà đường giải thích được; không phải tỷ lệ điểm nằm trên đường.`,`R² = 1 − RSS/TSS is the share of the variance of y the line explains; it is not the share of points on the line.`],"slr-assume":[`Muốn suy luận về độ dốc cần quan hệ thẳng, phần dư độc lập và độ tản đều (và phần dư xấp xỉ chuẩn khi mẫu nhỏ).`,`To make inferences about the slope you need a straight relationship, independent residuals and an even spread (and roughly normal residuals in small samples).`],"slr-resid":[`Phần dư e = y − ŷ; vẽ biểu đồ phần dư: dải ngẫu nhiên là tốt, hình cong hay hình kèn là cảnh báo.`,`The residual is e = y − ŷ; plot the residuals: a random band is good, a curve or funnel is a warning.`],"slr-test":[`Kiểm định độ dốc: t = β̂₁ / SE(β̂₁), hỏi nếu độ dốc thật bằng 0 thì độ dốc này có hiếm không.`,`Testing the slope: t = β̂₁ / SE(β̂₁), asking how rare a slope this far from 0 would be if the true slope were 0.`],"gd-cost":[`Hàm chi phí đo bộ hệ số hiện tại tệ đến đâu; với đường thẳng là J(w) = Σ(y − ŷ)².`,`The cost function measures how bad the current coefficients are; for a straight line it is J(w) = Σ(y − ŷ)².`],"gd-step":[`Gradient descent: w := w − η·∇J(w), mỗi bước đi ngược hướng dốc rồi lặp lại.`,`Gradient descent: w := w − η·∇J(w), each step goes against the slope, then repeats.`],"gd-rate":[`Tốc độ học η là độ dài mỗi bước: quá nhỏ thì chậm, quá lớn thì nhảy qua đáy.`,`The learning rate η is the length of each step: too small is slow, too large overshoots the bottom.`],"mlr-why":[`Hồi quy bội đưa nhiều cột vào một phương trình: ŷ = β₀ + β₁x₁ + β₂x₂ + ⋯.`,`Multiple regression puts several columns into one equation: ŷ = β₀ + β₁x₁ + β₂x₂ + ⋯.`],"mlr-coef":[`Hệ số của một cột là độ dốc của cột đó khi các cột khác trong mô hình được giữ cố định.`,`A coefficient is the slope of that column when the other columns in the model are held fixed.`],"mlr-vif":[`VIFⱼ = 1 / (1 − R²ⱼ); trên 5 là đáng lo (ứng với R²ⱼ > 0,8), vì các cột đầu vào đang đoán được nhau.`,`VIFⱼ = 1 / (1 − R²ⱼ); above 5 is worrying (R²ⱼ > 0.8) because the input columns are predicting each other.`],"mlr-dummy":[`Biến giả là cột 0/1 cho một mức của biến phân loại; mô hình có hệ số chặn thì bỏ đi một mức.`,`A dummy variable is a 0/1 column for one level of a categorical variable; with an intercept, one level is dropped.`],"mlr-select":[`R² không bao giờ giảm khi thêm cột, R² hiệu chỉnh thì có thể giảm: R²adj = 1 − (1 − R²)(n − 1)/(n − p − 1).`,`R² never falls when you add a column, adjusted R² can: R²adj = 1 − (1 − R²)(n − 1)/(n − p − 1).`],"logit-why":[`Hồi quy tuyến tính trên cột 0/1 có thể cho dự đoán ngoài khoảng 0 đến 1, nên không còn là xác suất.`,`Linear regression on a 0/1 column can predict outside 0 to 1, so it is no longer a probability.`],"logit-sig":[`Hồi quy logistic đưa điểm tuyến tính qua hàm sigmoid thành xác suất: P(y=1 ∣ x) = 1 / (1 + e^−(β₀+β₁x)).`,`Logistic regression passes a linear score through the sigmoid to get a probability: P(y=1 ∣ x) = 1 / (1 + e^−(β₀+β₁x)).`],"logit-odds":[`Điểm của logistic là log-odds; x tăng một đơn vị thì odds nhân với e^β₁, không phải cộng thêm xác suất.`,`The logistic score is the log-odds; one unit more of x multiplies the odds by e^β₁; it does not add probability.`],"logit-many":[`Logistic bội dùng cùng đường cong chữ S với điểm được dựng từ nhiều cột.`,`Multiple logistic regression uses the same S-curve with a score built from several columns.`],"logit-cm":[`Ma trận nhầm lẫn đếm bốn ô (TP, FP, FN, TN); accuracy = (TP + TN) / N chỉ là một con số trong bốn ô đó.`,`The confusion matrix counts four cells (TP, FP, FN, TN); accuracy = (TP + TN) / N is just one number from them.`],"logit-pr":[`Precision = TP/(TP+FP) cho biết danh sách gọi sạch đến đâu; recall = TP/(TP+FN) cho biết bắt được bao nhiêu người thật sự rời; hạ ngưỡng thì recall tăng, precision giảm.`,`Precision = TP/(TP+FP) says how clean the call list is; recall = TP/(TP+FN) says how many real leavers you catch; lowering the threshold raises recall and lowers precision.`],"logit-roc":[`Đường ROC vẽ tỷ lệ dương thật theo tỷ lệ dương giả khi quét ngưỡng từ cao xuống thấp.`,`The ROC curve plots the true positive rate against the false positive rate as the threshold sweeps from high to low.`],"logit-rest":[`Một-đấu-tất-cả: huấn luyện một hồi quy logistic cho mỗi nhãn, rồi so sánh các xác suất.`,`One-versus-rest trains one logistic regression per label, then compares the probabilities.`],"tree-ask":[`Cây quyết định hỏi một câu có/không ở mỗi nút; lá là một nhãn, hoặc một giá trị trung bình nếu dự đoán số.`,`A decision tree asks one yes/no question per node; a leaf is a label, or an average when predicting a number.`],"tree-gini":[`Gini G = 1 − Σpₖ² đo độ lẫn của một nút; câu hỏi tốt làm độ lẫn giảm.`,`Gini G = 1 − Σpₖ² measures how mixed a node is; a good question makes it fall.`],"tree-deep":[`Cây quá sâu học thuộc cả nhiễu của dữ liệu đã thấy; giới hạn độ sâu để chống quá khớp.`,`A tree that is too deep memorizes the noise of the data it has seen; limit the depth to prevent overfitting.`],"clus-why":[`Phân cụm nhóm các dòng theo khoảng cách giữa chúng khi bảng không có cột đáp án.`,`Clustering groups rows by the distance between them when the table has no answer column.`],"km-loop":[`K-means lặp hai bước: gán mỗi điểm cho tâm gần nhất, rồi dời mỗi tâm về trung bình các điểm của nó.`,`K-means repeats two steps: assign each point to the nearest center, then move each center to the mean of its points.`],"km-k":[`Đồ thị khuỷu tay là hình để nhìn, không phải phép kiểm định; chọn K ở chỗ thêm nhóm không còn siết cụm đáng kể.`,`The elbow plot is a picture to look at, not a test; pick K where adding a group no longer tightens the clusters much.`],hier:[`Phân cụm phân cấp gộp dần các nhóm gần nhau, rồi cắt cây ở một độ cao để được K nhóm; số nhóm là số nhánh bị cắt ngang.`,`Hierarchical clustering merges nearby groups step by step, then you cut the tree at a height to get K groups; K is the number of branches the cut crosses.`],"nlp-tok":[`Token là một mẩu văn bản; từ dừng là từ rất phổ biến được bỏ đi trước khi đếm.`,`A token is a piece of text; a stop word is a very common word dropped before counting.`],"nlp-bow":[`Túi từ đếm các token và bỏ thứ tự của từ.`,`Bag-of-words counts the tokens and throws away word order.`],"nlp-tfidf":[`TF-IDF = tf × log(N / df): từ xuất hiện trong mọi tài liệu thì có trọng số thấp.`,`TF-IDF = tf × log(N / df): a word found in every document gets a low weight.`],"nlp-edit":[`Khoảng cách chỉnh sửa là số thao tác một ký tự ít nhất để biến chuỗi này thành chuỗi kia; một lỗi gõ là một thao tác.`,`Edit distance is the fewest single-character edits to turn one string into another; one typo is one edit.`],"biz-map":[`Bắt đầu từ quyết định và con số có thể làm đổi quyết định; mô hình là bước cuối.`,`Start from the decision and the number that would change it; the model is the last step.`],"biz-metric":[`Đo thành công bằng con số nằm trong quyết định kinh doanh; accuracy, R² và AUC chỉ là dụng cụ, không phải mục tiêu.`,`Measure success with the number inside the business decision; accuracy, R² and AUC are instruments, not the goal.`],"pred-proj":[`Dự đoán là đoán dòng mới cùng loại với dữ liệu đã học; đẩy biến đến vùng chưa từng thấy rồi đọc đường thẳng là một giả định, không phải dự đoán.`,`Prediction guesses a new row of the same kind as the data learned from; pushing a variable to a region never seen and reading the line is an assumption, not a prediction.`],"logit-spec":[`Độ nhạy = TP/(TP+FN) là tỷ lệ người rời bạn bắt được; độ đặc hiệu = TN/(TN+FP) là tỷ lệ người ở lại bạn để yên; không cái nào là accuracy.`,`Sensitivity = TP/(TP+FN) is the share of leavers you catch; specificity = TN/(TN+FP) is the share of stayers you leave alone; neither is accuracy.`],"logit-who":[`Xác suất học từ nhóm nào chỉ nói về nhóm đó; đổi nhóm là đổi câu hỏi.`,`A probability learned on one group speaks only about that group; changing the group changes the question.`],"logit-drift":[`Mô hình đứng yên còn dữ liệu có thể đã đổi; điểm số cũ không tự đúng cho tháng mới.`,`The model stands still but the data may have changed; an old score doesn't automatically hold for the new month.`],"tree-line":[`Đường thẳng là một độ dốc cho cả khoảng; cây là các bậc thang và không tiếp tục leo ngoài vùng đã thấy.`,`A line is one slope across the whole range; a tree is steps and doesn't keep climbing outside the region seen.`],"tree-imp":[`Độ quan trọng của một cột trong cây là mức nó làm các nhóm sạch hơn qua các lần cắt; không phải tác động nhân quả lên kết quả.`,`A column's importance in a tree is how much it made the groups cleaner across its cuts; it is not a causal effect on the outcome.`],"tree-num":[`Cây hồi quy dự đoán một số bằng trung bình của lá, không có hệ số nhân.`,`A regression tree predicts a number with the average of its leaf; there is no multiplier coefficient.`],"km-start":[`K-means++ chọn tâm kế tiếp xa các tâm đã chọn; đó là cách khởi tạo, không phải cách chọn K.`,`K-means++ picks the next center far from the centers already chosen; it is a way to start, not a way to choose K.`],"link-how":[`Linkage là luật đo khoảng cách giữa hai cụm đang lớn lên; đổi luật thì hình dạng cụm đổi.`,`Linkage is the rule for measuring distance between two growing clusters; changing the rule changes the cluster shape.`],"db-scan":[`DBSCAN coi một vùng dày đặc là cụm; điểm không đủ láng giềng được để là nhiễu, không bị nhét vào cụm.`,`DBSCAN treats a dense region as a cluster; a point without enough neighbours is left as noise, not stuffed into a cluster.`],"gmm-soft":[`GMM cho mỗi điểm một tỷ lệ thuộc về từng đám mây hình bầu dục; đó là nhãn mềm, không phải nhãn cứng.`,`A GMM gives each point a share of belonging to each oval cloud; it is a soft label, not a hard one.`],"k-mode":[`K-modes dùng yếu vị (mode) làm tâm vì tên không có trung bình; K-prototype trộn cột chữ với cột số.`,`K-modes uses the mode as the center because a name has no mean; K-prototype mixes text columns with numeric columns.`],"nlp-stem":[`Stemming cắt đuôi từ theo luật; lemmatisation đưa từ về dạng từ điển; cả hai gộp các dạng của một từ, và có thể gộp nhầm hai từ khác nhau.`,`Stemming chops word endings by rule; lemmatisation returns a word to its dictionary form; both merge the forms of one word, and can wrongly merge two different words.`],"nlp-pmi":[`PMI(x, y) = log [P(x, y) / (P(x) P(y))]: cao khi hai từ đi cùng nhau nhiều hơn mức độc lập dự đoán; từ đi với mọi thứ thì điểm thấp.`,`PMI(x, y) = log [P(x, y) / (P(x) P(y))]: high when two words appear together more than independence predicts; a word that goes with everything scores low.`],"git-commit":[`Commit là ảnh chụp các tệp tại một thời điểm kèm một câu mô tả; không phải nút Save trong trí nhớ.`,`A commit is a snapshot of the files at one moment with a descriptive sentence; it is not a Save button in your memory.`],"git-branch":[`Nhánh là một dòng ảnh chụp riêng; nhánh chính không đổi cho đến khi bạn gộp nhánh thử vào.`,`A branch is a separate line of snapshots; the main branch doesn't change until you merge the trial line in.`],"sql-like":[`LIKE tìm theo mẫu đơn giản (chứa một cụm); regex dùng khi cần luật ký tự chính xác, và phải nói rõ hệ quản trị nào.`,`LIKE searches a simple pattern (contains a phrase); use regex when you need an exact character rule, and name the system.`],"sql-date":[`Kiểu ngày khác chuỗi trông giống ngày; bọc cột trong YEAR() thì chỉ mục không còn giúp lọc theo khoảng.`,`A date type differs from a string that looks like a date; wrapping a column in YEAR() stops its index from helping a range filter.`],"sql-nest":[`Truy vấn con không «cao cấp» hơn JOIN; chọn câu dễ đọc, đo thời gian nếu chậm, đừng lồng thêm cho oai.`,`A subquery isn't "more advanced" than a join; choose the readable query, measure the time if slow, and don't nest more for show.`],"sql-nwin":[`Đặt tên cho cửa sổ (WINDOW) chỉ là đặt tên, ý nghĩa phép tính không đổi.`,`Naming a window (WINDOW) is only naming; the meaning of the calculation is unchanged.`],"sql-proc":[`Thủ tục lưu sẵn là một kịch bản đã lưu có thể làm việc bên ngoài truy vấn; chỉ cần câu dễ đọc thì dùng CTE.`,`A stored procedure is a saved script that can act outside the query; if you only need a readable query, use a CTE.`],"sql-cur":[`Con trỏ đi từng dòng, một truy vấn xử lý cả tập; ưu tiên viết một câu lệnh.`,`A cursor goes row by row, while one query handles the whole set; prefer a single statement.`],"ens-vote":[`Tập hợp mô hình bỏ phiếu làm kết quả ít dao động hơn, nhưng không biến một cây sai thành đúng.`,`An ensemble vote makes the result fluctuate less, but doesn't turn a wrong tree into a right one.`],"ens-bag":[`Bagging cho mỗi mô hình một túi mẫu lấy lại (bootstrap): có dòng xuất hiện hai lần, có dòng bị bỏ ra.`,`Bagging gives each model a bootstrap bag: some rows appear twice and some are left out.`],"rf-col":[`Rừng ngẫu nhiên là bagging cộng luật mỗi lần cắt chỉ thấy một nhóm cột, làm các cây bớt giống nhau.`,`A random forest is bagging plus the rule that each cut sees only a group of columns, making trees less alike.`],"ens-oob":[`Dòng out-of-bag chấm điểm cây không chứa chúng; không phải dữ liệu tương lai, nên vẫn cần giữ riêng tập kiểm tra cuối.`,`Out-of-bag rows score the trees that didn't see them; they aren't future data, so keep a final test set aside.`],"imb-trap":[`Khi một lớp hiếm, gọi tất cả là lớp lớn vẫn đúng phần lớn; accuracy cao mà bỏ sót đúng thứ bạn cần tìm.`,`When one class is rare, calling everyone the big class is mostly right; high accuracy can still miss exactly what you need.`],"imb-fix":[`Nhân đôi dòng hiếm không tạo ra khách mới; trọng số đổi giá của một lỗi, và ngưỡng vẫn phải chọn.`,`Duplicating rare rows doesn't create new customers; weights change the price of a mistake, and the threshold still has to be chosen.`],"imb-smote":[`SMOTE tạo điểm nằm giữa chứ không tạo khách thật; chia dữ liệu trước, chỉ áp SMOTE trên tập huấn luyện.`,`SMOTE creates an in-between point, not a real customer; split first and apply SMOTE only on the training set.`],"bv-bias":[`Chệch (bias) là họ mô hình thiếu hình dạng; phương sai là đường đổi nhiều khi mẫu đổi; cả hai làm dự đoán mới sai.`,`Bias is a model family lacking enough shape; variance is a line that changes a lot as the sample changes; both make new predictions wrong.`],"reg-ridge":[`Ridge phạt tổng bình phương hệ số: hệ số co về 0 nhưng hiếm khi đúng bằng 0.`,`Ridge penalises the sum of squared coefficients: coefficients shrink toward 0 but rarely reach exactly 0.`],"reg-lasso":[`Lasso phạt tổng trị tuyệt đối hệ số và có thể đẩy một hệ số về đúng 0, tức là chọn cột.`,`Lasso penalises the sum of absolute coefficients and can push a coefficient to exactly 0, which selects columns.`],"met-reg":[`RMSE bình phương sai số rồi lấy căn nên phạt nặng một lần trượt lớn; MAE cộng sai số bỏ dấu rồi chia trung bình.`,`RMSE squares errors then takes the root, so it punishes one big miss hard; MAE averages the unsigned errors.`],"fe-num":[`Log kéo đuôi phải lại gần nhưng không có với 0, và đơn vị của hệ số đổi theo.`,`Log pulls a right-skewed tail closer but is undefined at 0, and the coefficient's unit changes with it.`],"fe-cat":[`Biến giả cho mỗi kênh một cột 0/1; có hệ số chặn thì bỏ một mức, giữ đủ mọi mức là cái bẫy cộng tuyến.`,`A dummy variable gives each channel a 0/1 column; with an intercept, drop one level, because keeping them all is a collinearity trap.`],"fe-time":[`Dấu thời gian thô chủ yếu chỉ nói «sau hơn»; muốn thứ, giờ, tháng thì phải tách ra.`,`A raw timestamp mostly says "later"; if you want weekday, hour or month, split them out.`],"cv-fold":[`Kiểm tra chéo giấu một phần mỗi vòng, học trên phần còn lại rồi lấy trung bình; chỉnh mô hình ngay trên các vòng đó làm điểm lạc quan.`,`Cross-validation hides one piece each round, learns on the rest, then averages; tuning on those same rounds makes the score optimistic.`],"cv-grid":[`Grid search thử mọi tổ hợp bạn liệt kê; random search bốc ngẫu nhiên trong khoảng bạn đặt; không cái nào tự phát minh núm vặn mới.`,`Grid search tries every combination you list; random search draws within a range you set; neither invents a new knob.`],"ts-order":[`Chuỗi thời gian là các số theo thứ tự thời gian; xáo trộn tuần là mất đúng điều cần dự báo.`,`A time series is numbers in time order; shuffling weeks loses exactly what you want to forecast.`],"ts-dep":[`Trong chuỗi tuần, tuần này giống tuần trước, nên sai số không độc lập và hồi quy thường cho độ tin cậy quá lạc quan.`,`In a weekly series this week resembles last week, so errors aren't independent and ordinary regression is too optimistic.`],"ts-decomp":[`Phân rã tách mức, xu hướng và mùa vụ; mùa vụ có thể là lượng cộng thêm (cộng) hoặc phép nhân (nhân).`,`Decomposition separates level, trend and season; a season can be an amount added (additive) or a multiplication (multiplicative).`],"ts-naive":[`Dự báo ngây thơ nói kỳ sau bằng kỳ trước; mô hình chuỗi thời gian nào cũng phải thắng nó trên dữ liệu chưa học.`,`The naive forecast says next period equals the last; every time-series model must beat it on data it hasn't learned from.`],"ts-sma":[`Trung bình trượt cộng vài kỳ gần nhất rồi chia, mỗi kỳ một phần bằng nhau; làm mượt nhưng chậm ở khúc ngoặt.`,`A moving average adds the last few periods and divides, each with an equal share; it smooths but is slow at turns.`],"ts-ses":[`Làm mượt hàm mũ: dự báo mới = α × giá trị gần nhất + (1 − α) × dự báo cũ; tuần gần nặng hơn tuần xa, không có xu hướng hay mùa.`,`Exponential smoothing: new forecast = α × latest value + (1 − α) × old forecast; recent weeks weigh more, with no trend or season.`],"ts-holt":[`Holt giữ một mức và một độ dốc; dự báo xa = mức + độ dốc × số bước, và độ dốc không tự dừng lại.`,`Holt keeps a level and a slope; a far forecast = level + slope × steps, and the slope doesn't switch off by itself.`],"ts-hw":[`Holt-Winters thêm thành phần mùa vào mức và độ dốc; chu kỳ là đầu vào bạn cung cấp, không phải kết quả máy tìm ra.`,`Holt-Winters adds a seasonal component to level and slope; the period is an input you supply, not a result the machine finds.`],"ts-mape":[`MAPE chia sai số cho giá trị thật nên tuần có 0 form làm nó hỏng, và giá trị rất nhỏ làm nó phình to.`,`MAPE divides the error by the actual value, so a week with 0 forms breaks it and a tiny value blows it up.`],"ts-walk":[`Chấm điểm chuỗi thời gian đi về phía trước: học trên quá khứ, chấm khoảng kế tiếp, rồi trượt cửa sổ; không giấu một mảnh ở giữa.`,`Scoring a time series goes forward: learn on the past, score the next stretch, then roll the window; don't hide a piece in the middle.`],"ts-stat":[`Chuỗi dừng có tâm và độ tản không phụ thuộc lúc bạn nhìn; xu hướng làm nó không dừng, và lấy sai phân giúp đưa về dừng.`,`A stationary series has a center and spread independent of when you look; a trend makes it non-stationary, and differencing helps.`],"ts-acf":[`ACF đo độ giống với tuần cách k bước; PACF đo phần còn lại sau khi đã tính các bước ở giữa.`,`ACF measures similarity with the week k steps away; PACF measures what remains after accounting for the steps in between.`],"ts-ar":[`Tự hồi quy (AR) dự đoán kỳ này từ vài kỳ trước: yₜ = c + φ·yₜ₋₁ + εₜ, không dùng cú sốc cũ.`,`Autoregression (AR) predicts this period from a few earlier ones: yₜ = c + φ·yₜ₋₁ + εₜ, with no old shocks.`],"ts-ma":[`Thành phần MA trong ARIMA nói kỳ này còn mang cú sốc gần đây (yₜ = μ + εₜ + θ·εₜ₋₁); nó không phải trung bình trượt.`,`The MA part of ARIMA says this period still carries recent shocks (yₜ = μ + εₜ + θ·εₜ₋₁); it is not a moving average.`],"ts-arima":[`ARIMA lấy sai phân cho chuỗi đứng yên rồi khớp AR và MA; SARIMA thêm mùa; SARIMAX thêm cột bên ngoài.`,`ARIMA differences the series to stand still then fits AR and MA; SARIMA adds a season; SARIMAX adds an outside column.`],"math-vec":[`Vectơ là các số đặt theo thứ tự cố định, mô tả một đối tượng bằng nhiều số; không phải bảng xếp hạng.`,`A vector is numbers in a fixed order that describe one object with several numbers; it is not a ranking.`],"math-add":[`Cộng vectơ là cộng từng ô cùng vị trí; nhân với một số là kéo giãn mọi ô cùng tỷ lệ.`,`Adding vectors is adding slots in the same position; multiplying by a number stretches every slot by the same ratio.`],"math-dot":[`Tích vô hướng u·v = Σ uᵢvᵢ nhân từng ô rồi cộng; lớn khi hai vectơ cùng hướng, bằng 0 khi vuông góc.`,`The dot product u·v = Σ uᵢvᵢ multiplies slot by slot and adds; it is large when vectors point the same way and 0 when perpendicular.`],"math-mat":[`Ma trận là bảng số có nhiệm vụ biến vectơ vào thành vectơ ra.`,`A matrix is a table of numbers whose job is to turn an input vector into an output vector.`],"math-mul":[`Nhân ma trận: mỗi hàng bên trái nhân vô hướng với mỗi cột bên phải; đổi thứ tự hai ma trận thường cho kết quả khác.`,`Matrix multiplication: each row on the left is dotted with each column on the right; swapping the order usually gives a different result.`],"math-det":[`Định thức là hệ số nhân diện tích (hay thể tích) khi ma trận tác động lên một hình; bằng 0 nghĩa là hình bị dẹt; với 2×2, det = ad − bc.`,`The determinant is the factor by which area (or volume) is multiplied; 0 means the shape is flattened; for 2×2, det = ad − bc.`],"math-sys":[`Hệ phương trình tuyến tính hỏi có vectơ nào thỏa mọi phương trình cùng lúc; kết quả có thể là một nghiệm, vô số nghiệm hoặc vô nghiệm.`,`A linear system asks whether any vector satisfies every equation at once; the result is one solution, infinitely many, or none.`],"math-ls":[`Khi không có nghiệm đúng, bình phương tối thiểu chọn x làm ‖Ax − b‖² nhỏ nhất; đó là ý tưởng của đường hồi quy.`,`With no exact solution, least squares picks x minimising ‖Ax − b‖²; it is the idea behind the regression line.`],"math-eig":[`Av = λv: vectơ riêng là hướng chỉ bị kéo giãn hoặc lật, không quay; trị riêng λ là hệ số kéo giãn đó.`,`Av = λv: an eigenvector is a direction only stretched or flipped, not rotated; the eigenvalue λ is that stretch factor.`],"math-deriv":[`Đạo hàm là độ dốc của tiếp tuyến tại một điểm; cùng một đường cong có chỗ dốc, chỗ phẳng.`,`The derivative is the slope of the tangent at one point; the same curve can be steep here and flat there.`],"math-crit":[`Điểm tới hạn là nơi độ dốc bằng 0; có thể là đỉnh, đáy hoặc chỗ phẳng không phải cả hai; đạo hàm bậc hai giúp phân biệt.`,`A critical point is where the slope is 0; it can be a peak, a bottom or a flat spot; the second derivative helps tell them apart.`],"math-part":[`Đạo hàm riêng ∂f/∂x là độ dốc khi chỉ một biến đổi, các biến khác giữ cố định.`,`A partial derivative ∂f/∂x is the slope when only one variable changes and the others are held fixed.`],"math-grad":[`Gradient là vectơ các đạo hàm riêng, chỉ hướng hàm tăng nhanh nhất; gradient descent đi ngược nó: w ← w − η∇J.`,`The gradient is the vector of partial derivatives and points where the function rises fastest; gradient descent goes against it: w ← w − η∇J.`],"math-jac":[`Jacobian là bảng các đạo hàm riêng khi đầu ra là một danh sách số: Jᵢⱼ = ∂fᵢ/∂xⱼ.`,`The Jacobian is the table of partial derivatives when the output is a list of numbers: Jᵢⱼ = ∂fᵢ/∂xⱼ.`],"math-hess":[`Hessian là bảng đạo hàm bậc hai, cho biết chỗ đứng cong lên, cong xuống hay là điểm yên ngựa.`,`The Hessian is the table of second derivatives and says whether the spot curves up, curves down, or is a saddle.`],"math-taylor":[`Khai triển Taylor bậc một: f(x) ≈ f(a) + f′(a)(x − a); gần điểm a đường cong giống tiếp tuyến, càng xa càng sai.`,`First-order Taylor: f(x) ≈ f(a) + f′(a)(x − a); near a the curve looks like its tangent, and the farther away, the worse.`],"math-p":[`Xác suất là một tỷ lệ; mẫu số là tập đầy đủ mà bạn đang nói tới.`,`Probability is a ratio; the denominator is the whole set you are talking about.`],"math-or":[`P(A hoặc B) = P(A) + P(B) − P(A và B); trừ phần đã đếm hai lần.`,`P(A or B) = P(A) + P(B) − P(A and B); subtract the part counted twice.`],"math-and":[`P(A và B) = P(A) × P(B ∣ A); nhân xác suất thứ hai tính trong những lần thứ nhất đã xảy ra.`,`P(A and B) = P(A) × P(B ∣ A); multiply by the second probability computed among the times the first happened.`],"math-perm":[`Đổi chỗ tạo kết quả khác thì dùng hoán vị: P(n,k) = n! / (n−k)!.`,`If swapping places creates a different outcome, use a permutation: P(n,k) = n! / (n−k)!.`],"math-comb":[`Tổ hợp: một tập đếm một lần dù xoay thế nào; C(n,k) = n! / (k!(n−k)!) là hoán vị chia cho số cách sắp xếp trong tập.`,`Combination: one set counts once however it is turned; C(n,k) = n! / (k!(n−k)!) is the permutation divided by the ways to arrange within a set.`],"math-disj":[`Rời nhau là biết A xảy ra thì xác suất B bằng 0; độc lập là biết A không đổi xác suất B; hai biến cố rời nhau có xác suất dương thì không độc lập.`,`Disjoint means knowing A happened sets B's chance to 0; independent means knowing A doesn't change B's chance; disjoint events with positive probability aren't independent.`],"math-kind":[`Ba cách hiểu xác suất: cổ điển (đếm khả năng đều nhau), tần suất (lặp lại nhiều lần) và mức độ tin; gọi tên loại trước khi cộng hay nhân.`,`Three readings of probability: classical (equally likely cases), frequency (many repeats) and degree of belief; name the kind before adding or multiplying.`],"ds-type":[`Kiểu cột quyết định phép tính nào được phép: số, nhãn, nhãn có thứ tự; lấy trung bình cột tên là sai kiểu.`,`A column's type decides which operations are allowed: number, label, ordered label; averaging a column of names is the wrong type.`],"ds-center":[`Trung bình = tổng / n bị giá trị cực đoan kéo mạnh; trung vị là giá trị giữa sau khi sắp xếp và ít bị kéo.`,`The mean = total / n is pulled hard by extreme values; the median is the middle value after sorting and is barely pulled.`],"ds-mode":[`Yếu vị (mode) là giá trị xuất hiện nhiều nhất; một cột có thể có một, nhiều hoặc không rõ yếu vị.`,`The mode is the value that appears most often; a column can have one, several, or no clear mode.`],"ds-q":[`Tứ phân vị cắt dãy đã sắp xếp thành bốn phần gần bằng nhau; IQR = Q₃ − Q₁; phân vị là cùng ý với tỷ lệ bất kỳ.`,`Quartiles cut a sorted list into four nearly equal parts; IQR = Q₃ − Q₁; a percentile is the same idea with any ratio.`],"ds-pct":[`Phân vị là một vị trí trong dãy đã sắp xếp; phải sắp xếp trước và nói rõ quy ước cắt.`,`A percentile is a position in a sorted series; sort first and state the cutting convention.`],"ds-var":[`Phương sai là trung bình bình phương độ lệch quanh trung bình; mẫu chia cho n − 1 (s² = Σ(x − x̄)² / (n − 1)), cả tổng thể chia cho n.`,`Variance is the average squared deviation around the mean; a sample divides by n − 1 (s² = Σ(x − x̄)² / (n − 1)), a whole population by n.`],"ds-sd":[`Độ lệch chuẩn s = √s² là căn bậc hai của phương sai và có cùng đơn vị với dữ liệu gốc.`,`Standard deviation s = √s² is the square root of variance and has the same unit as the original data.`],"ds-range":[`Khoảng biến thiên = max − min chỉ nhìn hai đầu của dãy, không phản ánh độ tản của cả dãy.`,`Range = max − min looks only at the two ends, not the spread of the whole series.`],"ds-mad":[`MAD = (1/n) Σ∣xᵢ − x̄∣ cộng độ lệch bỏ dấu rồi chia n; không có căn, nên không phải độ lệch chuẩn.`,`MAD = (1/n) Σ∣xᵢ − x̄∣ adds the unsigned deviations and divides by n; no root, so it is not the standard deviation.`],"ds-cov":[`Hiệp phương sai dương khi hai cột thường nằm cùng phía so với trung bình của chúng, âm khi nằm khác phía.`,`Covariance is positive when two columns are usually on the same side of their means, negative when on opposite sides.`],"ds-corr":[`Tương quan r = cov(x, y) / (sₓ·s_y) bỏ đơn vị nhưng vẫn không phải nhân quả.`,`Correlation r = cov(x, y) / (sₓ·s_y) removes the unit but is still not causation.`],"c0-order":[`Học các khóa theo thứ tự giáo trình, vì khóa sau dựa vào kiến thức khóa trước.`,`Study the courses in syllabus order, because a later course relies on the knowledge of the one before.`],"c0-read":[`Mỗi thẻ là một ý có hình và một câu nói đúng; dừng lại khi định nghĩa khớp với hình.`,`Each card is one idea with a picture and a statement said correctly; stop when the definition matches the picture.`],"crisp-biz":[`CRISP-DM bắt đầu bằng hiểu bài toán kinh doanh: ai quyết định, quyết định gì; câu hỏi kinh doanh đi trước tệp dữ liệu.`,`CRISP-DM starts with business understanding: who decides and what they decide; the business question comes before the data file.`],"crisp-data":[`Dữ liệu thô chưa phải câu trả lời; bước hiểu dữ liệu kiểm tra tệp có đo đúng quyết định đã chốt không.`,`Raw data isn't yet an answer; data understanding checks whether the file measures the decision that was fixed.`],"crisp-prep":[`Ba bước giữa của CRISP-DM là chuẩn bị dữ liệu, xây mô hình và đánh giá; làm sạch để dữ liệu hỏi được, và mô hình chưa phải quyết định.`,`The middle three CRISP-DM steps are data preparation, modeling and evaluation; clean the data so it can be asked, and a model isn't yet a decision.`],"crisp-ship":[`Triển khai là đưa kết quả vào công việc thật rồi theo dõi khi công việc đổi.`,`Deployment is putting the result into real work, then monitoring as the work changes.`],"ps-open":[`Giải quyết vấn đề đi qua sáu bước, mỗi bước trả lời một câu hỏi khác nhau.`,`Solving a problem goes through six steps, each answering a different question.`],"ps-type":[`Loại vấn đề quyết định cách đặt câu hỏi; gọi tên loại vấn đề trước khi chọn công cụ.`,`The kind of problem decides how the question is asked; name it before choosing a tool.`],"ps-fact":[`Sự kiện đo được khác ý kiến; ghi hai thứ ở hai cột riêng.`,`A measurable fact differs from an opinion; record them in two separate columns.`],"ps-smart":[`SMART là một câu mô tả mục tiêu: Cụ thể, Đo được, Khả thi, Liên quan, Có thời hạn; năm tiêu chí gói trong một câu.`,`SMART is a sentence describing a goal: Specific, Measurable, Achievable, Relevant, Time-bound; five criteria packed into one sentence.`],"ps-rank":[`Ưu tiên là bỏ bớt chứ không phải đánh số mọi thứ; một hạn chót nuôi một việc chính, việc khác ghi là chưa làm.`,`Prioritizing is dropping things, not numbering everything; one deadline feeds one main task, and others are recorded as not done yet.`],"ps-cause":[`Nguyên nhân đáng hành động là cái bạn đổi được; tách cái đổi được khỏi bối cảnh xung quanh.`,`A cause worth acting on is one you can change; separate it from the context around it.`],"ps-opt":[`Mỗi phương án viết kèm hậu quả, không viết kèm tính từ.`,`Write each option with its consequence, not with an adjective.`],"ps-do":[`Sau khi hành động, đo lại bằng chính câu bạn đã viết, đừng chỉ tin cảm giác.`,`After acting, measure again with the sentence you wrote; don't just trust the feeling.`],"xl-cell":[`Mỗi ô có một kiểu (số, chữ, công thức) quyết định phép tính hợp lệ; SUM bỏ qua ô chữ, nên kiểm tra kiểu trước khi cộng.`,`Each cell has a type (number, text, formula) that decides which operations are valid; SUM skips text cells, so check the type before adding.`],"xl-lock":[`Dấu $ giữ cố định địa chỉ khi kéo công thức: $A$1 giữ cả cột và hàng, A$1 giữ hàng, $A1 giữ cột.`,`The $ sign keeps an address fixed when dragging: $A$1 keeps column and row, A$1 keeps the row, $A1 keeps the column.`],"xl-if":[`IF chọn một nhánh; ô trống không phải FALSE; viết từ trường hợp đặc biệt đến trường hợp còn lại, và có nhánh riêng cho ô trống.`,`IF picks one branch; an empty cell isn't FALSE; write from the special case to the remaining case, with its own branch for empty cells.`],"xl-keep":[`Lọc chỉ ẩn dòng, xóa thì mất; muốn loại khỏi phép đếm hãy viết điều kiện, đừng xóa.`,`Filtering only hides rows, deleting loses them; to exclude from a count, write a condition rather than delete.`],"xl-chart":[`Biểu đồ cột so sánh nhóm, biểu đồ đường theo dõi thời gian; chọn theo câu hỏi cần trả lời, không theo mẫu đẹp.`,`Bar charts compare groups, line charts follow time; choose by the question to answer, not by a nice template.`],"xl-pivot":[`PivotTable gom dòng, không tạo khách mới; xác định một dòng của bảng nguồn là gì trước khi kéo trường.`,`A PivotTable groups rows, it doesn't create new customers; establish what one source row is before dragging fields.`],"xl-look":[`VLOOKUP chỉ nhìn sang phải và mặc định có thể khớp gần đúng; khớp chính xác thì viết FALSE, nhìn sang trái thì dùng INDEX kết hợp MATCH.`,`VLOOKUP only looks right and may default to approximate matching; write FALSE for an exact match and use INDEX with MATCH to look left.`],"py-run":[`Python chạy từ trên xuống, tên phải được tạo trước khi dùng; khi lỗi thì sửa dòng mà lỗi chỉ ra.`,`Python runs top to bottom and a name must be created before use; when there's an error, fix the line it points to.`],"py-type":[`Kiểu dữ liệu quyết định phép toán hợp lệ: "3" + "4" ra "34", còn 3 + 4 ra 7; kiểm tra kiểu trước khi tính.`,`Data type decides which operation is valid: "3" + "4" gives "34" while 3 + 4 gives 7; check the type before calculating.`],"py-op":[`Một dấu = là gán, hai dấu == là so sánh; chia có hai loại.`,`One = assigns, two == compares; and division comes in two kinds.`],"py-if":[`if chỉ cho một nhánh chạy mỗi lần; viết nhánh hẹp trước.`,`An if statement lets only one branch run each time; write the narrow branch first.`],"py-loop":[`for đi qua mọi phần tử của tập đã biết; while chỉ dùng khi viết được điều kiện dừng, nếu không có thể không bao giờ dừng.`,`for walks every element of a known collection; use while only when you can write a stopping condition, or it may never stop.`],"py-fn":[`Hàm trả về gì thì nơi gọi nhận cái đó; không có return thì trả về None; print chỉ để người đọc.`,`Whatever a function returns is what the caller gets; no return means None; print is only for human eyes.`],"py-str":[`Thao tác trên chuỗi trả về chuỗi mới, chuỗi cũ không đổi; muốn giữ bản đã làm sạch thì phải gán lại.`,`String operations return a new string and the old one doesn't change; reassign if you want to keep the cleaned copy.`],"py-list":[`List có thứ tự, sửa được và đánh chỉ số từ 0; cắt lát tạo bản sao mới.`,`A list is ordered, editable and indexed from 0; slicing makes a new copy.`],"py-dict":[`Từ điển thiếu khóa thì báo lỗi, chỉ get chấp nhận vắng khóa; dùng get khi vắng khóa là có thể xảy ra.`,`A dictionary raises an error on a missing key, only get tolerates absence; use get when a missing key is possible.`],"py-tup":[`Tuple có thứ tự nhưng không cho sửa từng ô; dùng cho một dòng dữ liệu không muốn bị sửa tại chỗ.`,`A tuple is ordered but doesn't allow editing slot by slot; use it for a data row you don't want edited in place.`],"py-set":[`Set loại trùng và không hứa thứ tự; dùng để hỏi «ai có mặt», không dùng để giữ thứ tự theo tuần.`,`A set removes duplicates and promises no order; use it to ask "who is there", not to keep weekly order.`],"py-np":[`Mảng NumPy chứa một kiểu dữ liệu, xếp thành hình chữ nhật; chỉ đưa số vào mảng số.`,`A NumPy array holds one data type in a rectangle; put only numbers into a numeric array.`],"py-ser":[`Series cộng theo nhãn (index) chứ không theo vị trí mắt thấy; kiểm tra index trước khi cộng hai cột.`,`A Series adds by label (index), not by the position the eye sees; check the index before adding two columns.`],"py-frame":[`DataFrame: loc dùng nhãn, iloc dùng vị trí, và lát cắt loc gồm cả đầu mút cuối; nói rõ bạn đang cầm nhãn hay vị trí.`,`DataFrame: loc uses labels, iloc uses positions, and a loc slice includes the end; state whether you hold labels or positions.`],"py-plot":[`Biểu đồ là một câu trả lời, trục phải có đơn vị; chọn biểu đồ theo câu hỏi và đừng để trục tự nói dối.`,`A chart is an answer and the axis must have a unit; choose by the question and don't let the axis lie.`],"py-g1":[`Đây là bài chấm điểm; ý mới nằm ở C1, và khi bí thì quay lại các thẻ Python cơ bản.`,`This is a graded assessment; the new ideas are in C1, and when stuck, go back to the basic Python cards.`],"py-g2":[`Bài chấm điểm thư viện xoay quanh đơn vị dòng, nhãn và lát cắt; khi bí mở lại bốn thẻ thư viện.`,`The library assessment revolves around row unit, labels and slices; when stuck, reopen the four library cards.`],"tb-why":[`Một biểu đồ trả lời một câu hỏi; trang trí không phải phân tích; viết câu hỏi trước rồi mới kéo trường.`,`A chart answers one question; decoration isn't analysis; write the question first, then drag in the fields.`],"tb-bar":[`Cột để so sánh nhóm; đường chỉ khi trục là một thứ tự thật như thời gian.`,`Bars compare groups; lines only when the axis is a real order like time.`],"tb-box":[`Box plot cho thấy độ tản («tập này rộng cỡ nào»); bản đồ chỉ khi câu hỏi là «ở đâu» và địa điểm là thật.`,`A box plot shows spread ("how wide is this set"); a map only when the question is "where" and the places are real.`],"tb-part":[`Bánh và treemap thể hiện các phần của một tổng; dùng bánh cho một tổng và ít lát, còn lại dùng cột.`,`Pies and treemaps show parts of a whole; use a pie for one total and few slices, otherwise bars.`],"tb-join":[`Nối bảng trước khi vẽ vì phép nối có thể nhân dòng; đếm trước khi nối hoặc nối theo khóa một-một.`,`Join the tables before charting, because a join can multiply rows; count before joining or join on a one-to-one key.`],"tb-calc":[`Trường tính toán là một công thức, không phải phép đo mới từ thực tế.`,`A calculated field is a formula, not a new measurement from reality.`],"tb-dual":[`Mỗi trang cho một quyết định; hai trục phải thể hiện hai đơn vị, có hai nhãn hoặc tách thành hai hình.`,`One page for one decision; two axes must show two units, with two labels or two pictures.`],"xa-text":[`Hàm văn bản trả về văn bản, không tự đổi chữ thành số; làm sạch chữ là một bước, đổi sang số là bước sau (VALUE hoặc *1).`,`Text functions return text, they don't turn text into numbers; cleaning is one step, converting to a number a later one (VALUE or *1).`],"xa-count":[`COUNT đếm ô số, COUNTA đếm ô không rỗng; đếm tên dùng COUNTA, đếm số đo dùng COUNT.`,`COUNT counts numeric cells, COUNTA counts non-empty cells; use COUNTA for names and COUNT for measurements.`],"xa-match":[`INDEX kết hợp MATCH nhìn sang trái được, VLOOKUP thì không; khóa không nằm ở cột trái nhất thì đừng dùng VLOOKUP.`,`INDEX with MATCH can look left, VLOOKUP cannot; when the key isn't the leftmost column, don't use VLOOKUP.`],"xa-what":[`Đổi một ô đầu vào là thử công thức, không phải thấy tương lai; gọi đó là phép thử, đừng gọi là dự báo.`,`Changing an input cell tests the formula, it doesn't show the future; call it a test, not a forecast.`],"xa-macro":[`Macro lặp lại các cú bấm, không ra quyết định; dùng cho việc lặp nhàm chán, quyết định nằm ngoài macro.`,`A macro repeats clicks and doesn't make decisions; use it for dull repetition, decisions live outside it.`],"pb-model":[`Mô hình là các bảng và quan hệ; một visual là một câu hỏi hỏi trên mô hình; chốt quan hệ trước rồi mới tin visual.`,`The model is tables and relationships; a visual is one question asked of it; fix the relationships first, then trust the visual.`],"pb-pq":[`Power Query là một công thức; làm mới chạy lại công thức đó; giữ các bước câu hỏi cần và ghi lại các bước đã bỏ.`,`Power Query is a formula and refresh runs it again; keep the steps the question needs and record the steps you dropped.`],"pb-grain":[`Hạt dữ liệu là «một dòng là gì»; đếm dòng là đếm đúng thứ đó; viết hạt vào tên bảng.`,`The grain is "what one row is"; counting rows counts that; write the grain into the table name.`],"pb-dax":[`Cột tính toán lưu giá trị cho từng dòng; measure tính trong bộ lọc đang áp dụng; số cần đi theo bộ lọc thì là measure, số là thuộc tính của dòng thì là cột tính toán.`,`A calculated column stores a value per row; a measure computes in the active filter; a number that should follow the filter is a measure, a row property is a calculated column.`],"pb-page":[`Một trang cho một quyết định; viết một câu hỏi ở đầu trang, visual không phục vụ nó thì chuyển sang trang khác.`,`One page for one decision; write one question at the top, and move a visual that doesn't serve it to another page.`],"pb-rls":[`RLS là luật áp lên người xem, không phải slicer; muốn giấu dữ liệu thì viết role, và DAX không gỡ được bộ lọc RLS.`,`RLS is a rule on the viewer, not a slicer; to hide data, write a role, and DAX cannot lift RLS filters.`],"pb-refresh":[`Làm mới kéo lại dòng theo công thức; measure không lưu số hôm qua; kiểm tra giờ làm mới thành công gần nhất trước khi nói số là của hôm nay.`,`Refresh pulls rows by formula; a measure doesn't store yesterday; check the last successful refresh time before saying a number is today's.`],"fw-5why":[`Hỏi «tại sao» đến khi gặp thứ bạn đổi được; năm không phải con số thần kỳ; dừng ở quy trình, không dừng ở một người.`,`Ask why until you reach something you can change; five is not magic; stop at the process, not at a person.`],"fw-spin":[`SPIN là bốn loại câu hỏi để hiểu vấn đề, không phải kịch bản để người ta gật đầu.`,`SPIN is four kinds of questions to understand the problem, not a script to make people nod.`],"fw-ask":[`Câu hỏi chưa phải phán quyết; ghi câu hỏi một cột, câu trả lời một cột, kết luận khi đã có thước đo.`,`A question isn't yet a verdict; put questions in one column, answers in another, and conclude once you have a yardstick.`],"fw-bmc":[`Chín ô là chín giả thuyết; chữ điền vào chưa phải bằng chứng; mỗi ô cần một câu kiểm chứng được hoặc ghi chưa có cơ sở.`,`Nine boxes are nine hypotheses; filled-in text isn't evidence; each box needs a testable sentence or a note that there is no basis yet.`],"fw-mece":[`MECE: các nhánh không chồng lấn và cộng lại phủ hết câu hỏi; mỗi dòng có đúng một chỗ.`,`MECE: branches don't overlap and together cover the question; each row has exactly one place.`],"fw-7p":[`7P là danh sách kiểm tra cho dịch vụ, không phải bảng xếp hạng; đi qua đủ bảy mục.`,`7P is a checklist for services, not a ranking; go through all seven items.`],"fw-5c":[`5C là năm phía cần nhìn trước khi chọn; mỗi phía một câu có thể bị chứng minh sai, nếu không thì phía đó còn trống.`,`5C is five sides to look at before choosing; one sentence per side that could be shown wrong, otherwise that side is still empty.`],"st-shape":[`Một câu chuyện dữ liệu có ba phần: bình thường, vướng mắc và quyết định; chỉ một điều cần chốt.`,`A data story has three parts: the normal, the snag and the decision; exactly one thing to settle.`],"st-who":[`Viết xuống người nghe quyết định được gì và có bao nhiêu phút trước khi viết slide.`,`Write down what the listener can decide and how many minutes they have before writing slides.`],"st-insight":[`Một insight có năm dạng: xu hướng, khác biệt, tỷ trọng, ngoại lai và cùng nhau; gọi tên dạng rồi chọn biểu đồ.`,`An insight has five shapes: trend, difference, share, outlier and together; name the shape, then choose the chart.`],"st-pyramid":[`Nói quyết định trước, lý do sau; câu đầu là điều cần chốt, không phải lời chào.`,`Say the decision first, the reasons after; the first sentence is the thing to settle, not a greeting.`],"st-one":[`Hai tiêu đề là hai câu chuyện nên tách ra; mỗi trang chỉ đòi một điều.`,`Two headlines are two stories, so split them; each page asks for only one thing.`],"st-board":[`Storyboard là thứ tự các câu, không phải bảng màu; xếp câu trước, màu sau và chỉ để dễ đọc câu.`,`A storyboard is the order of sentences, not a color palette; order the sentences first, colors later and only to ease reading.`],"or-obj":[`Mục tiêu và biến quyết định là hai thứ khác nhau; một ô cho mục tiêu, các ô khác cho biến.`,`The objective and the decision variables are different things; one cell for the objective, other cells for the variables.`],"or-con":[`Mỗi giới hạn là một tài nguyên không tiêu được hai lần; một bất đẳng thức cho mỗi tài nguyên.`,`Each limit is a resource that can't be spent twice; one inequality per resource.`],"or-sens":[`Phân tích độ nhạy chỉ đúng khi nghiệm còn ở cùng một đỉnh; đọc khoảng cho phép, ngoài khoảng đó phải giải lại.`,`Sensitivity holds only while the solution stays at the same vertex; read the allowed range and solve again outside it.`],"or-solv":[`Bài toán tuyến tính cho nghiệm ở một đỉnh; bài toán cong có thể dừng ở cực trị địa phương nên thử nhiều điểm xuất phát.`,`A linear problem finds a vertex; a curved one may stop at a local optimum, so try several starting points.`],"or-sheet":[`Solver chỉ đọc các ô bạn trỏ tới; mỗi giới hạn phải là một ô công thức được khai báo, không phải một ghi chú.`,`Solver reads only the cells you point to; every limit must be a declared formula cell, not a note.`],"ga-next":[`Token kế tiếp được sinh ra, không tra từ cơ sở dữ liệu; muốn số từ một tệp thì đưa tệp vào.`,`The next token is generated, not looked up in a database; to get a number from a file, supply the file.`],"ga-vs":[`Học máy dự đoán một cột; GenAI viết tiếp một đoạn văn; gọi đúng tên công việc trước khi chọn thước đo.`,`Machine learning predicts a column; GenAI continues a passage of text; name the job correctly before choosing the yardstick.`],"ga-stack":[`Mô hình, dữ liệu và sản phẩm là ba lớp khác nhau; nói rõ bạn đang chạm lớp nào.`,`Model, data and product are three different layers; state which layer you are touching.`],"ga-use":[`Một ca sử dụng là một công việc kèm cái giá của văn bản sai; viết cái giá của một lỗi trước khi đưa vào công việc.`,`A use case is a job together with the price of wrong text; write down the cost of one mistake before using it.`],"ga-chat":[`Messages là chữ mô hình thấy trong lần gọi này, không phải trí nhớ về thế giới; muốn mô hình thấy gì thì đưa vào messages của lần gọi này.`,`Messages are the text the model sees in this call, not a memory of the world; put what you want it to see in this call's messages.`],"ga-temp":[`Temperature đổi độ đa dạng của cách diễn đạt, không đổi độ đúng.`,`Temperature changes the variety of wording, not the truth.`],"ga-tok":[`Token là đơn vị tính tiền và đơn vị độ dài; đếm độ dài trước và chỉ đưa phần công việc cần.`,`Tokens are the unit of billing and of length; count the length first and supply only the part the job needs.`],"ga-prompt":[`Một prompt gồm nhiệm vụ, ngữ cảnh và định dạng đầu ra; đủ ba phần, bỏ lời động viên.`,`A prompt is the task, the context and the output format; all three parts, no pep talk.`],"ga-few":[`Vài ví dụ cho thấy định dạng nhưng không chứng minh nó khớp thực tế; dùng ví dụ để cố định khuôn câu, không thay cho dữ liệu.`,`A few examples show a format but don't prove it matches reality; use them to fix the sentence format, not to replace data.`],"ga-cot":[`Yêu cầu mô hình viết từng bước không phải là chứng minh; đọc xem bước nào chỉ về nguồn trong ngữ cảnh và bỏ bước không có nguồn.`,`Asking the model to write step by step is not a proof; read which steps point to a source in the context and drop those that don't.`],"sa-tune":[`Tinh chỉnh đổi trọng số; RAG đổi tài liệu trong prompt; tài liệu hay đổi thì dùng RAG, giọng ổn định mà dữ kiện ít đổi mới cân nhắc tinh chỉnh.`,`Fine-tuning changes the weights; RAG changes the documents in the prompt; use RAG for changing documents, consider fine-tuning only for a stable tone with rarely changing facts.`],"sa-react":[`Nghĩ, gọi công cụ, nhìn kết quả; đừng bịa kết quả của công cụ; mỗi dữ kiện lấy từ hệ thống phải có một lần gọi và một kết quả.`,`Think, call a tool, look at the result; don't invent the tool's result; every fact from a system must have one call and one result.`],"sa-stage":[`Ba giai đoạn: nói từ prompt, gọi danh mục, rồi chấm các ca; giai đoạn không có log là chưa xảy ra.`,`Three stages: speak from the prompt, call the catalog, then score the cases; a stage with no log hasn't happened.`],"sa-tool":[`Giá và tồn kho lấy từ danh mục, không từ câu trả lời nghe hay; không có dòng danh mục thì không có giá trong câu trả lời.`,`Price and stock come from the catalog, not from a nice-sounding answer; without a catalog row, there is no price in the answer.`],"sa-score":[`Chấm từng ca đã viết; nhiều câu trả lời giống nhau không phải sự thật; thước đo là kết quả danh mục hoặc một câu trong chính sách.`,`Score each written case; several matching answers aren't truth; the yardstick is the catalog result or a policy sentence.`],"rag-why":[`Tệp của bạn chưa nằm sẵn trong mô hình; muốn bám tệp phải có bước truy xuất và phải thấy đoạn nào vào prompt.`,`Your file isn't already inside the model; to stay with the file there must be a retrieval step, and you must see which passages entered the prompt.`],"rag-emb":[`Gần nhau trong không gian embedding không phải khớp từ khóa và cũng chưa phải đúng; coi điểm gần là ứng viên, đọc đoạn văn rồi mới quyết.`,`Close in embedding space isn't a keyword match and isn't correct; treat a close score as a candidate and read the passage before deciding.`],"rag-chunk":[`Cắt đoạn là cắt nghĩa; một điều khoản bị cắt đôi không còn là điều khoản; cắt sao cho một mệnh đề nằm trọn trong một mảnh, hoặc đưa thêm mảnh kề.`,`Cutting passages cuts meaning; a split clause is no longer a clause; cut so a clause stays whole in one piece, or supply adjacent pieces too.`],"rag-vec":[`Đoạn gần nhất chưa chắc là đoạn đúng; lấy vài đoạn, đọc rồi mới viết; top-1 không phải kết luận.`,`The nearest passage isn't necessarily the correct one; take a few, read them, then write; top-1 isn't a conclusion.`],"rag-idx":[`Đổi tệp mà không dựng lại chỉ mục thì truy xuất thấy bản cũ; mỗi lần nguồn đổi phải dựng lại chỉ mục hoặc có cách ghi phiên bản.`,`Changing a file without rebuilding the index makes retrieval see the old version; rebuild on every source change or record versions.`],"rag-rank":[`Xếp hạng lại là đọc lần hai một danh sách có sẵn, không phải nguồn mới; đừng mong nó tìm ra đoạn chưa được truy xuất.`,`Re-ranking is a second reading of an existing list, not a new source; don't hope it finds a passage that wasn't retrieved.`],"rag-near":[`Một demo tìm được đoạn văn chưa phải đánh giá; giữ một bộ ca để chấm, demo chỉ là một câu trong bộ đó.`,`A demo that finds a passage isn't an evaluation; keep a set of cases to score, the demo is just one question in it.`],"rag-store":[`Một bộ sưu tập là một kho có tên; các kho khác không tự được tìm; ghi tên kho vào log.`,`A collection is a named store; other stores aren't searched automatically; put the store name in the log.`],"rag-demo":[`Một lần chạy RAG in ra câu trả lời chưa phải chấm điểm; giữ đoạn đã truy xuất cạnh câu đã viết, không có cặp đó thì chưa có ca.`,`One RAG run printing an answer isn't scoring; keep the retrieved passage beside the written sentence, without that pair there is no case.`],"rag-job":[`Dự án RAG trả lời từ các tài liệu được giao, không từ trí nhớ; không có trong bộ thì nói «không tìm thấy», đừng bổ sung từ trí nhớ.`,`The RAG project answers from the assigned documents, not from memory; if it isn't in the set, say not found, don't supplement from memory.`],"im-grid":[`Ảnh là một lưới số (mỗi điểm 0–255), chưa phải sự thật; gọi là lưới được sinh ra, đừng gọi là ảnh tư liệu.`,`An image is a grid of numbers (each 0–255), not yet a fact; call it a generated grid, not a documentary photo.`],"im-vae":[`VAE giữ cái chung, nên ảnh dựng lại bị mờ vì chi tiết riêng bị bỏ; đừng dùng bản giải nén làm kho lưu trữ.`,`A VAE keeps what is common, so the rebuilt image is blurry because the specifics are dropped; don't use the decompressed version as an archive.`],"im-gan":[`GAN gồm một người làm giả và một người chấm: «giống ảnh thật» nghĩa là giống tập huấn luyện, không phải giống thực tế.`,`A GAN is a forger and a critic: "looks like a real image" means looks like the training set, not like reality.`],"im-diff":[`Khuếch tán học cách khử nhiễu, không tra kho ảnh; gọi là lưới đã khử nhiễu và kiểm tra nếu định dùng làm tư liệu.`,`Diffusion learns to remove noise, it doesn't look up an image store; call it a denoised grid and check it before using it as documentation.`],"im-txt":[`Prompt lái bức ảnh nhưng không chứng nhận nó; dùng ảnh sinh ra làm phác thảo, duyệt bằng mắt người và tài sản thật.`,`A prompt steers the picture but doesn't certify it; use a generated image as a sketch and approve it with human eyes and real assets.`],"lc-tpl":[`Template là khuôn có chỗ trống; LangChain báo lỗi khi thiếu biến; thiếu biến thì dừng hoặc nói là thiếu, đừng gọi mô hình.`,`A template is a mold with blanks; LangChain raises an error when a variable is missing; if one is missing, stop or say so, don't call the model.`],"lc-parse":[`Parser đòi một định dạng; mô hình không tuân thủ thì parser báo lỗi; báo lỗi, đừng thay bằng một con số.`,`A parser demands a format; if the model doesn't comply, it errors; report the error, don't replace it with a number.`],"lc-agent":[`Chain là đường đi vẽ sẵn, agent tự chọn bước kế tiếp; chain khi đường rõ, agent khi bước kế phụ thuộc câu hỏi; cả hai cần giới hạn số bước.`,`A chain is a pre-drawn path, an agent picks its next step; use a chain when the path is clear, an agent when the next step depends on the question; both need a step cap.`],"cap-none":[`Khóa này là bài tập, giáo trình không có buổi dạy thêm; làm bài bằng các ý đã học.`,`This course is an assignment, the syllabus has no extra teaching session; do it with the ideas already learned.`]};function r(r,i){var a;let o=t(r);if(!o)return null;let s=e(o,i),c=(a=n[r])==null?void 0:a[+(i===`en`)],l=[`Thẻ: ${s.title}`,s.plain&&`Nói đơn giản: ${s.plain}`,s.situation&&`Tình huống: ${s.situation}`,s.precise&&`Chính xác: ${s.precise}`,s.formula&&`Công thức: ${s.formula}`,c&&`Nhớ một câu: ${c}`].filter(Boolean).join(`
`);return{id:r,title:s.title,text:l.slice(0,6e3)}}var i={vi:{again:`Giải thích lại thẻ này bằng một ví dụ khác, đơn giản, từng bước. Cuối cùng tóm một câu để nhớ.`,quiz:`Ra cho mình 3 câu hỏi kiểm tra về thẻ này (khó dần). Hỏi từng câu một, chờ mình trả lời rồi mới chấm và giải thích.`,mistake:`Người mới học thẻ này hay nhầm chỗ nào nhất? Cho ví dụ sai và ví dụ đúng.`,free:``},en:{again:`Explain this card again with a different simple example, step by step. End with a one-line takeaway.`,quiz:`Give me 3 quiz questions on this card, getting harder. Ask one at a time, wait for my answer, then grade and explain.`,mistake:`Where do beginners most often go wrong on this card? Show a wrong and a right example.`,free:``}};function a(e,t,n,r=``){let a=`Mình đang học Data Science (thống kê, Excel, SQL, Python, học máy). Đây là thẻ học mình đang đọc. Hãy bám đúng nội dung thẻ, không bịa số liệu, trả lời bằng tiếng Việt ngắn gọn.`,o=e===`free`?r.trim():i[n][e];return[t?`${a}\n\n${t.text}`:a,o&&`Yêu cầu: ${o}`].filter(Boolean).join(`

`)}export{a as n,n as r,r as t};